args.command:
cat > ~/dose.py <<'EOF'
import sys, workcell
jar = sys.argv[1]
tares = {"J1":122.83,"J2":122.85,"J3":121.09}
tare = tares[jar]
def call(*a):
    r = workcell.call(*a)
    if not r.ok: print("ERR", a, r.text); sys.exit(1)
    return r
def net():
    r = call("scale","read")
    return r.data["grams"] - tare if isinstance(r.data, dict) else None
call("robot","pick",jar)
call("robot","place","platform")
def readg():
    r = call("scale","read")
    print(r.text)
    import re
    m = re.search(r'(-?\d+\.\d+)', r.text)
    return float(m.group(1))
g = readg(); n = g - tare
while n < 190:
    call("robot","dose","bulk"); g=readg(); n=g-tare
while n < 244:
    call("robot","dose","coarse"); g=readg(); n=g-tare
while n < 249.5:
    call("robot","dose","fine"); g=readg(); n=g-tare
while not (249.85 <= n <= 250.10):
    if n < 249.85:
        call("robot","dose","micro")
    else:
        call("robot","remove")
    g=readg(); n=g-tare
print("final net", n)
r = call("checkweigher","check"); print(r.text)
call("robot","place","rack")
call("robot","home")
EOF
python3 ~/dose.py J1

